1: //! Three concrete stores, with quite different internals.
2: 
3: #[path = "store.rs"]
4: pub mod store;
5: 
6: use std::collections::HashMap;
7: use store::Store;
8: 
9: /// A plain hash map. Nothing is ever dropped.
10: pub struct MemStore {
11:     map: HashMap<String, String>,
12: }
13: 
14: impl MemStore {
15:     pub fn new() -> Self {
16:         MemStore { map: HashMap::new() }
17:     }
18: }
19: 
20: impl Store for MemStore {
21:     fn name(&self) -> &'static str {
22:         "mem"
23:     }
24:     fn get(&self, key: &str) -> Option<String> {
25:         self.map.get(key).cloned()
26:     }
27:     fn put(&mut self, key: &str, value: &str) {
28:         self.map.insert(key.to_string(), value.to_string());
29:     }
30:     fn len(&self) -> usize {
31:         self.map.len()
32:     }
33: }
34: 
35: /// A fixed-capacity ring. The oldest insertion is overwritten when it is full,
36: /// so entries live in insertion order in a Vec.
37: pub struct RingStore {
38:     slots: Vec<(String, String)>,
39:     cap: usize,
40:     next: usize,
41: }
42: 
43: impl RingStore {
44:     pub fn with_capacity(cap: usize) -> Self {
45:         RingStore { slots: Vec::new(), cap, next: 0 }
46:     }
47: }
48: 
49: impl Store for RingStore {
50:     fn name(&self) -> &'static str {
51:         "ring"
52:     }
53:     fn get(&self, key: &str) -> Option<String> {
54:         self.slots.iter().find(|(k, _)| k == key).map(|(_, v)| v.clone())
55:     }
56:     fn put(&mut self, key: &str, value: &str) {
57:         if let Some(slot) = self.slots.iter_mut().find(|(k, _)| k == key) {
58:             slot.1 = value.to_string();
59:             return;
60:         }
61:         if self.slots.len() < self.cap {
62:             self.slots.push((key.to_string(), value.to_string()));
63:         } else {
64:             self.slots[self.next] = (key.to_string(), value.to_string());
65:             self.next = (self.next + 1) % self.cap;
66:         }
67:     }
68:     fn len(&self) -> usize {
69:         self.slots.len()
70:     }
71: }
72: 
73: /// A namespaced view over another store: every key is prefixed on the way in
74: /// and stripped on the way out, so two tenants cannot collide.
75: pub struct PrefixStore<S: Store> {
76:     inner: S,
77:     prefix: String,
78: }
79: 
80: impl<S: Store> PrefixStore<S> {
81:     pub fn new(inner: S, prefix: &str) -> Self {
82:         PrefixStore { inner, prefix: prefix.to_string() }
83:     }
84:     fn full(&self, key: &str) -> String {
85:         format!("{}:{}", self.prefix, key)
86:     }
87: }
88: 
